example.description:
Example recurring expense YAML (an 18-month phone contract with a price step and an exit fee; numbers made up):

apiVersion: ud/v1
kind: RecurringExpense
spec:
  name: Acme Mobile phone contract
  vendor: Acme Mobile
  currency: SGD
  starts_at: "2027-01-08"
  first_due: "2027-02-08"
  frequency: {unit: month, interval: 1}
  committed_until: "2028-07-07"
  exit_fee: {base: 540.00, mode: prorata_remaining}
  terms:
    - {amount: 29.90, effective_from: "2027-01-08"}
    - {amount: 44.90, effective_from: "2027-02-08", reason: launch discount ends}
    - {amount: 49.90, effective_from: "2028-07-08", reason: loyalty discount ends}
